import sympy

def divisors_count(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
    return count

def solve():
    # Search for the smallest positive integer with exactly 25 divisors
    n = 1
    while True:
        if divisors_count(n) == 25:
            return n
        n += 1

candidate = 1296

# Independent check
def check():
    # Check divisors count using sympy
    if sympy.divisors(candidate).__len__() == 25:
        # Also verify it's the minimum by checking all numbers up to candidate-1
        for i in range(1, candidate):
            if sympy.divisors(i).__len__() == 25:
                return False, i
        return True, candidate
    return False, None

is_valid, min_found = check()
if is_valid:
    ans = candidate
else:
    ans = min_found

print(f"ANSWER: {sympy.latex(ans)}")
