import sympy as sp

def solve():
    # We want the smallest positive integer n such that z^n - 1 = 0 and (z - sqrt(3))^n - 1 = 0 have a common root.
    # A common root z means:
    # 1) z^n = 1  => z is an n-th root of unity, so z = exp(i * 2*pi*k / n) for some 0 <= k < n.
    # 2) (z - sqrt(3))^n = 1 => z - sqrt(3) is also an n-th root of unity, so z - sqrt(3) = exp(i * 2*pi*m / n) for some 0 <= m < n.

    # Let's search n starting from 1.
    for n in range(1, 100):
        # Generate all n-th roots of unity
        roots1 = {sp.exp(sp.I * 2 * sp.pi * k / n) for k in range(n)}

        # For the second equation, z - sqrt(3) is an n-th root of unity, 
        # which means z = omega + sqrt(3) where omega is an n-th root of unity.
        roots2 = {sp.exp(sp.I * 2 * sp.pi * m / n) + sp.sqrt(3) for m in range(n)}

        # Check for intersection using numerical approximation to handle symbolic comparisons safely
        found = False
        for z1 in roots1:
            z1_val = z1.evalf()
            for z2 in roots2:
                z2_val = z2.evalf()
                if abs(z1_val - z2_val) < 1e-9:
                    found = True
                    break
            if found:
                break

        if found:
            ans = n
            break

    print(f"ANSWER: {sp.latex(ans)}")

if __name__ == '__main__':
    solve()
