import sympy

def solve():
    # A 4x4 grid has 16 squares, indexed 0 to 15.
    # We want to find the number of subsets of squares (configurations of coins) 
    # such that:
    # 1. No two coins are orthogonally adjacent.
    # 2. Every 2x2 square contains at least one coin.

    # Precompute orthogonal adjacencies
    adj = []
    for r in range(4):
        for c in range(4):
            idx = r * 4 + c
            neighbors = []
            if r > 0: neighbors.append((r-1)*4 + c)
            if r < 3: neighbors.append((r+1)*4 + c)
            if c > 0: neighbors.append(r*4 + c - 1)
            if c < 3: neighbors.append(r*4 + c + 1)
            adj.append(neighbors)

    # Precompute 2x2 squares
    # There are 3x3 = 9 such squares
    squares = []
    for r in range(3):
        for c in range(3):
            s = [
                r * 4 + c,
                r * 4 + c + 1,
                (r + 1) * 4 + c,
                (r + 1) * 4 + c + 1
            ]
            squares.append(s)

    # Brute force all 2^16 = 65536 configurations
    count = 0
    for mask in range(1 << 16):
        # Check condition 1: No two coins are orthogonally adjacent
        valid = True
        for i in range(16):
            if (mask & (1 << i)):
                for n_idx in adj[i]:
                    if (mask & (1 << n_idx)):
                        valid = False
                        break
            if not valid:
                break

        if not valid:
            continue

        # Check condition 2: Each 2x2 square has at least one coin
        for s in squares:
            has_coin = False
            for i in s:
                if (mask & (1 << i)):
                    has_coin = True
                    break
            if not has_coin:
                valid = False
                break

        if valid:
            count += 1

    ans = sympy.Integer(count)
    print(f"ANSWER: {sympy.latex(ans)}")

solve()
