def solve():
    # HATER + HEART = EARTH
    # H * 10000 + A * 1000 + T * 100 + E * 10 + R
    # + H * 10000 + E * 1000 + A * 100 + R * 10 + T
    # = E * 10000 + A * 1000 + R * 100 + T * 10 + H

