                        hater = H * 10000 + A * 1000 + T * 100 + E * 10 + R
                        heart = H * 10000 + E * 1000 + A * 100 + R * 10 + T
                        earth = E * 10000 + A * 1000 + R * 100 + T * 10 + H

                        if hater + heart == earth:
                            solutions.append(earth)

    # We are looking for the unique 5-digit integer EARTH
    # Let's print the unique solution found
    unique_solutions = list(set(solutions))
